#include <iomanip>
#include <iostream>
#include <string>

int main() {
    std::string producto = "Café 250 g";
    int cantidad = 3;
    double precio = 12.5;
    constexpr double igv = 0.18;

    double subtotal = cantidad * precio;
    double impuesto = subtotal * igv;
    double total = subtotal + impuesto;

    std::cout << std::fixed << std::setprecision(2);
    std::cout << "Producto: " << producto << '\n';
    std::cout << "Subtotal: S/ " << subtotal << '\n';
    std::cout << "IGV:      S/ " << impuesto << '\n';
    std::cout << "Total:    S/ " << total << '\n';
    return 0;
}

