#include <iostream>
#include <string>

int main() {
    std::string nombre;
    std::string carrera;
    int ciclo = 0;

    std::cout << "Nombre: ";
    std::getline(std::cin, nombre);
    std::cout << "Carrera: ";
    std::getline(std::cin, carrera);
    std::cout << "Ciclo: ";
    std::cin >> ciclo;

    std::cout << "\n--- Ficha ---\n";
    std::cout << nombre << " | " << carrera << " | ciclo " << ciclo << '\n';
    return 0;
}

#include <iomanip>
#include <iostream>

int main() {
    double celsius = 0.0;
    std::cout << "Temperatura en grados Celsius: ";
    std::cin >> celsius;

    double fahrenheit = celsius * 9.0 / 5.0 + 32.0;

    std::cout << std::fixed << std::setprecision(1);
    std::cout << celsius << " C = " << fahrenheit << " F\n";
    return 0;
}

